(function() {
    'use strict';

    class InnovationPipelineAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Innovation Pipeline: R&D Portfolio';
            this.version = '1.1.0';
            this.BUDGET = 18.0;
            this.PROJECTS = [
                { id: 'centinela', horizon: 3, type: 'disruptive', minViable: 2.5, stageOrder: 0, maxRevenue: 12, techFeas: 0.65 },
                { id: 'ecopack', horizon: 1, type: 'sustaining', minViable: 1.0, stageOrder: 0, maxRevenue: 4, techFeas: 0.80 },
                { id: 'malla', horizon: 2, type: 'disruptive', minViable: 2.8, stageOrder: 1, maxRevenue: 18, techFeas: 0.55 },
                { id: 'nexgen7', horizon: 1, type: 'sustaining', minViable: 3.5, stageOrder: 1, maxRevenue: 42, techFeas: 0.87 },
                { id: 'gemelo', horizon: 2, type: 'disruptive', minViable: 2.5, stageOrder: 2, maxRevenue: 15, techFeas: 0.60 },
                { id: 'premier', horizon: 1, type: 'sustaining', minViable: 2.8, stageOrder: 2, maxRevenue: 18, techFeas: 0.90 },
                { id: 'nexservice', horizon: 2, type: 'disruptive', minViable: 2.0, stageOrder: 3, maxRevenue: 22, techFeas: 0.78 },
                { id: 'latamfit', horizon: 1, type: 'sustaining', minViable: 1.5, stageOrder: 3, maxRevenue: 12, techFeas: 0.95 }
            ];
            this.STAGES = ['basic', 'applied', 'prototype', 'commercial', 'market'];
            this.STAGE_THRESHOLD = [2, 2, 2, 1];
        }

        initialize(state) {
            // Reseed when there is no submitted history: the framework calls
            // initialize() again after undoing the first year, and v1.0.0's
            // "domainState is empty" guard never fired, so killed/launched projects
            // and the chart history survived the undo.
            var noHistory = !state.history || state.history.length === 0;
            if (!state.domainState || Object.keys(state.domainState).length === 0 || noHistory) {
                state.domainState = {
                    revenue: 340,
                    ebitdaMargin: 11.4,
                    baseRevDecline: 0,
                    innovationHealth: 42,
                    projects: {},
                    revenueHistory: [],
                    ebitdaHistory: [],
                    healthHistory: [],
                    h1History: [],
                    h2History: [],
                    h3History: [],
                    zombieTotal: 0,
                    killTotal: 0,
                    launchedDisruptive: 0,
                    launchedSustaining: 0,
                    cumulativeDisruptiveInvest: 0,
                    cumulativeSustainingInvest: 0,
                    eventLog: ''
                };
                var self = this;
                self.PROJECTS.forEach(function(p) {
                    state.domainState.projects[p.id] = {
                        stageIdx: p.stageOrder,
                        active: true,
                        killed: false,
                        periodsAdequate: 0,
                        totalInvested: 0,
                        launched: false,
                        launchedAtPeriod: 0,
                        zombie: false
                    };
                });
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    centinela: 2.0,
                    ecopack: 1.0,
                    malla: 2.5,
                    nexgen7: 4.0,
                    gemelo: 2.0,
                    premier: 3.0,
                    nexservice: 1.5,
                    latamfit: 2.0
                };
            }
            this._setupInputListeners();
            this._updateProjectStatuses(state.domainState);
        }

        _setupInputListeners() {
            var self = this;
            var ids = ['centinela','ecopack','malla','nexgen7','gemelo','premier','nexservice','latamfit'];
            ids.forEach(function(pid) {
                var el = document.getElementById('alloc_' + pid);
                if (el) {
                    el.addEventListener('input', function() {
                        self._recalcBudget();
                        try {
                            self._updateKillWarning(window.mySimulation.state.domainState);
                        } catch (e) { /* pre-init */ }
                    });
                }
            });
            self._recalcBudget();
        }

        _recalcBudget() {
            var ids = ['centinela','ecopack','malla','nexgen7','gemelo','premier','nexservice','latamfit'];
            var total = 0;
            ids.forEach(function(pid) {
                var el = document.getElementById('alloc_' + pid);
                if (el) total += parseFloat(el.value) || 0;
            });
            total = Math.round(total * 10) / 10;
            var remaining = Math.round((this.BUDGET - total) * 10) / 10;
            var allocEl = document.getElementById('allocatedDisplay');
            var remEl = document.getElementById('remainingDisplay');
            if (allocEl) allocEl.textContent = '$' + total.toFixed(1) + 'M';
            if (remEl) {
                remEl.textContent = '$' + remaining.toFixed(1) + 'M';
                remEl.style.color = remaining < 0 ? '#e74c3c' : (remaining > 0.5 ? '#e67e22' : '#27ae60');
            }
        }

        _t(key, fallback) {
            try {
                var s = window.mySimulation;
                if (s && typeof s.t === 'function') {
                    var v = s.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) { /* ignore */ }
            return fallback;
        }

        _lang() {
            try { return (window.mySimulation && window.mySimulation.currentLanguage) || 'en'; }
            catch (e) { return 'en'; }
        }

        _activeCount(ds) {
            var n = 0;
            this.PROJECTS.forEach(function(p) {
                var ps = ds.projects[p.id];
                if (ps && !ps.killed && !ps.launched) n++;
            });
            return n;
        }

        _updateProjectStatuses(ds) {
            var self = this;
            // v1.0.0 always rendered the English stage names — the `es` array was dead.
            var stageNames = {
                en: ['Basic Research', 'Applied Research', 'Prototype', 'Commercial Dev', 'Launched'],
                es: ['Inv. Básica', 'Inv. Aplicada', 'Prototipo', 'Des. Comercial', 'Lanzado']
            };
            var names = stageNames[self._lang()] || stageNames.en;
            var KILLED = self._t('status_killed', 'KILLED');
            var LAUNCHED = self._t('status_launched', 'LAUNCHED');
            var ZOMBIE = self._t('status_zombie', 'ZOMBIE');
            self.PROJECTS.forEach(function(p) {
                var ps = ds.projects[p.id];
                var statusEl = document.getElementById('status' + p.id.charAt(0).toUpperCase() + p.id.slice(1));
                var inputEl = document.getElementById('alloc_' + p.id);
                if (!statusEl || !ps) return;
                if (ps.killed) {
                    statusEl.innerHTML = '<span style="color:#e74c3c;">' + KILLED + '</span>';
                    if (inputEl) { inputEl.value = 0; inputEl.disabled = true; }
                } else if (ps.launched) {
                    statusEl.innerHTML = '<span style="color:#27ae60;">' + LAUNCHED + '</span>';
                    if (inputEl) { inputEl.value = 0; inputEl.disabled = true; }
                } else {
                    if (inputEl) inputEl.disabled = false;   // re-enable after an undo
                    var sn = names[ps.stageIdx] || '';
                    if (ps.zombie) {
                        statusEl.innerHTML = '<span style="color:#e67e22;">' + ZOMBIE + ' — ' + sn + '</span>';
                    } else {
                        statusEl.innerHTML = '<span style="color:#2980b9;">' + sn + ' (' + ps.periodsAdequate + '/' + self.STAGE_THRESHOLD[ps.stageIdx] + ')</span>';
                    }
                }
            });
            self._updateKillWarning(ds);
        }

        // Funding a live project with $0 kills it permanently, on submit, with no
        // confirmation in v1.0.0. Surface it live, before the click.
        _updateKillWarning(ds) {
            var self = this;
            var box = document.getElementById('killWarning');
            if (!box) return;
            var pending = [];
            var below = [];
            self.PROJECTS.forEach(function(p) {
                var ps = ds.projects[p.id];
                if (!ps || ps.killed || ps.launched) return;
                var el = document.getElementById('alloc_' + p.id);
                var v = el ? (parseFloat(el.value) || 0) : 0;
                var label = self._t('proj_' + p.id + '_name', p.id.toUpperCase());
                if (v === 0) pending.push(label);
                else if (v < p.minViable) below.push(label + ' (min $' + p.minViable + 'M)');
            });
            var html = '';
            if (pending.length) {
                html += '<div class="innov-sim-kill-line">⚠️ ' + self._t('kill_warning', 'These projects will be KILLED PERMANENTLY on submit (zero funding):') + ' <strong>' + pending.join(', ') + '</strong></div>';
            }
            if (below.length) {
                html += '<div class="innov-sim-zombie-line">🧟 ' + self._t('zombie_warning', 'Funded below minimum viable — these become zombie projects:') + ' <strong>' + below.join(', ') + '</strong></div>';
            }
            box.innerHTML = html;
            box.style.display = html ? 'block' : 'none';
        }

        validateDecisions(decisions) {
            var ids = ['centinela','ecopack','malla','nexgen7','gemelo','premier','nexservice','latamfit'];
            var total = 0;
            var ds = window.mySimulation.state.domainState;
            var self = this;
            ids.forEach(function(pid) {
                var el = document.getElementById('alloc_' + pid);
                if (el) {
                    var ps = ds.projects[pid];
                    if (ps.killed || ps.launched) {
                        decisions[pid] = 0;
                    } else {
                        var v = parseFloat(el.value);
                        decisions[pid] = isFinite(v) ? Math.round(Math.max(0, v) * 10) / 10 : 0;
                    }
                    total += decisions[pid];
                }
            });
            total = Math.round(total * 10) / 10;

            var active = self._activeCount(ds);

            // DEAD-END FIX. v1.0.0 rejected any submission under $16M. Once every
            // project was killed or launched the maximum possible allocation was $0,
            // so the year could never be submitted and the run was stuck for good.
            // With no live projects there is nothing to fund — let the year close.
            if (active === 0) return true;

            if (total > self.BUDGET + 0.05) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_over_warning'), 'warning'
                );
                return false;
            }
            if (total < self.BUDGET - 2.0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_under_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var self = this;
            var events = [];
            var yearZombies = 0;
            var yearKills = 0;
            var yearLaunches = 0;
            var h1Alloc = 0;
            var h2Alloc = 0;
            var h3Alloc = 0;
            var disruptiveAlloc = 0;
            var sustainingAlloc = 0;
            var totalAlloc = 0;

            self.PROJECTS.forEach(function(p) {
                var ps = ds.projects[p.id];
                if (ps.killed || ps.launched) return;
                var alloc = d[p.id] || 0;
                totalAlloc += alloc;
                ps.totalInvested += alloc;

                if (p.horizon === 1) h1Alloc += alloc;
                else if (p.horizon === 2) h2Alloc += alloc;
                else h3Alloc += alloc;

                if (p.type === 'disruptive') disruptiveAlloc += alloc;
                else sustainingAlloc += alloc;

                if (alloc === 0) {
                    ps.killed = true;
                    ps.active = false;
                    ps.zombie = false;
                    yearKills++;
                    ds.killTotal++;
                    events.push(p.id.toUpperCase() + ': Project killed (zero funding)');
                } else if (alloc < p.minViable) {
                    ps.zombie = true;
                    ps.periodsAdequate = Math.max(0, ps.periodsAdequate - 1);
                    yearZombies++;
                    ds.zombieTotal++;
                    events.push(p.id.toUpperCase() + ': Zombie — funded below minimum viable ($' + p.minViable + 'M needed)');
                } else {
                    ps.zombie = false;
                    ps.periodsAdequate++;
                    var threshold = self.STAGE_THRESHOLD[ps.stageIdx];
                    if (ps.periodsAdequate >= threshold && ps.stageIdx < 4) {
                        var techRoll = Math.random();
                        if (techRoll < p.techFeas) {
                            ps.stageIdx++;
                            ps.periodsAdequate = 0;
                            if (ps.stageIdx === 4) {
                                ps.launched = true;
                                ps.launchedAtPeriod = state.currentPeriod;
                                yearLaunches++;
                                if (p.type === 'disruptive') ds.launchedDisruptive++;
                                else ds.launchedSustaining++;
                                events.push(p.id.toUpperCase() + ': LAUNCHED to market!');
                            } else {
                                var sNames = ['Basic', 'Applied', 'Prototype', 'Commercial', 'Market'];
                                events.push(p.id.toUpperCase() + ': Advanced to ' + sNames[ps.stageIdx]);
                            }
                        } else {
                            events.push(p.id.toUpperCase() + ': Gate review — technical setback, remains in current stage');
                        }
                    }
                }
            });

            ds.cumulativeDisruptiveInvest += disruptiveAlloc;
            ds.cumulativeSustainingInvest += sustainingAlloc;

            var disruptionPressure = 0.04 + (state.currentPeriod * 0.012);
            var baseRevLoss = ds.revenue * disruptionPressure;
            ds.baseRevDecline += baseRevLoss;

            var newRevenue = 0;
            self.PROJECTS.forEach(function(p) {
                var ps = ds.projects[p.id];
                if (!ps.launched) return;
                var yearsLive = state.currentPeriod - ps.launchedAtPeriod + 1;
                if (p.type === 'sustaining') {
                    var decay = Math.max(0.4, 1.0 - (yearsLive - 1) * 0.12);
                    newRevenue += p.maxRevenue * decay * 0.3;
                } else {
                    var growth = Math.min(1.0, yearsLive * 0.35);
                    newRevenue += p.maxRevenue * growth * 0.25;
                }
            });

            ds.revenue = Math.max(200, 340 - ds.baseRevDecline + newRevenue);
            ds.revenue = Math.round(ds.revenue * 10) / 10;

            var marginBase = 11.4 - (state.currentPeriod * 0.7);
            var marginBoost = (newRevenue / 340) * 8;
            var zombiePenalty = yearZombies * 0.4;
            ds.ebitdaMargin = Math.max(3, Math.round((marginBase + marginBoost - zombiePenalty) * 10) / 10);

            var h1Pct = totalAlloc > 0 ? Math.round((h1Alloc / totalAlloc) * 100) : 0;
            var h2Pct = totalAlloc > 0 ? Math.round((h2Alloc / totalAlloc) * 100) : 0;
            var h3Pct = totalAlloc > 0 ? 100 - h1Pct - h2Pct : 0;

            var balanceScore = 0;
            if (h1Pct >= 55 && h1Pct <= 70) balanceScore += 30;
            else if (h1Pct >= 45 && h1Pct <= 75) balanceScore += 15;
            if (h2Pct >= 20 && h2Pct <= 30) balanceScore += 30;
            else if (h2Pct >= 15 && h2Pct <= 35) balanceScore += 15;
            if (h3Pct >= 8 && h3Pct <= 15) balanceScore += 20;
            else if (h3Pct >= 5 && h3Pct <= 20) balanceScore += 10;

            var killScore = Math.min(20, yearKills * 10 + (ds.killTotal > 0 ? 5 : 0));
            // Guard the divide: totalAlloc is 0 when every project is killed/launched
            // (and in the competition preview, which runs this on every keystroke with
            // whatever is in the boxes). v1.0.0 produced NaN → NaN health on screen.
            var disruptScore = totalAlloc > 0 ? Math.min(30, (disruptiveAlloc / totalAlloc) * 60) : 0;

            ds.innovationHealth = Math.min(100, Math.max(0, Math.round(balanceScore + killScore + disruptScore)));
            if (!isFinite(ds.innovationHealth)) ds.innovationHealth = 0;

            ds.revenueHistory.push(ds.revenue);
            ds.ebitdaHistory.push(ds.ebitdaMargin);
            ds.healthHistory.push(ds.innovationHealth);
            ds.h1History.push(h1Pct);
            ds.h2History.push(h2Pct);
            ds.h3History.push(h3Pct);

            ds.eventLog = events.join('<br>');

            // Grading contract (results_utils.php :: express_resolveDomainScore):
            // domainState.performance.overallScore, else a top-level numeric score.
            // v1.0.0 only produced a score in getPerformanceSummary() at the very end,
            // so the instructor panel showed "—" and the exported grade was empty.
            var sc = this._score(ds);
            ds.performance = ds.performance || {};
            ds.performance.overallScore = sc;
            ds.score = sc;

            // calculateResults() must stay pure: usf-engine.js
            // _computeCompetitionPreview() runs it on a CLONE on every input change.
            // v1.0.0 wrote #eventsPanel here and scheduled _updateProjectStatuses(ds)
            // bound to that clone — so previewing a $0 box disabled and zeroed the real
            // input 500 ms later, and the events panel showed events that never
            // happened. DOM writes now live in _syncUI(), on the period lifecycle.
            return {
                period: state.currentPeriod,
                h1Pct: h1Pct,
                h2Pct: h2Pct,
                h3Pct: h3Pct,
                revenue: ds.revenue,
                ebitdaMargin: ds.ebitdaMargin,
                innovationHealth: ds.innovationHealth,
                zombies: yearZombies,
                kills: yearKills,
                launches: yearLaunches,
                disruptiveAlloc: Math.round(disruptiveAlloc * 10) / 10,
                sustainingAlloc: Math.round(sustainingAlloc * 10) / 10,
                eventLog: ds.eventLog,
                score: sc
            };
        }

        // Single scorer — the same five pillars getPerformanceSummary() reports, run
        // every year so the grading layer always has a value.
        _score(ds) {
            var n = ds.h1History.length || 1;
            var avgH1 = ds.h1History.reduce(function(s, v) { return s + v; }, 0) / n;

            var balanceScore = (avgH1 >= 55 && avgH1 <= 70) ? 25 : ((avgH1 >= 45 && avgH1 <= 75) ? 15 : 5);

            var disruptScore = 5;
            var totalInvest = ds.cumulativeDisruptiveInvest + ds.cumulativeSustainingInvest;
            if (totalInvest > 0) {
                var dp = ds.cumulativeDisruptiveInvest / totalInvest;
                disruptScore = (dp >= 0.35 && dp <= 0.55) ? 25 : ((dp >= 0.25 && dp <= 0.60) ? 15 : 5);
            }

            var killDiscScore = (ds.killTotal >= 1 && ds.killTotal <= 3) ? 20 : (ds.killTotal > 3 ? 10 : 5);
            var coherenceScore = (ds.zombieTotal <= 2) ? 20 : (ds.zombieTotal <= 5 ? 12 : 5);
            var commScore = 10;

            return Math.max(0, Math.min(100, balanceScore + disruptScore + killDiscScore + coherenceScore + commScore));
        }

        // Lifecycle-driven UI refresh (was a setTimeout inside calculateResults).
        _syncUI(state) {
            if (!state || !state.domainState) return;
            var ds = state.domainState;
            this._updateProjectStatuses(ds);
            this._recalcBudget();
            var evPanel = document.getElementById('eventsPanel');
            var evContent = document.getElementById('eventsContent');
            if (evPanel && evContent) {
                if (ds.eventLog) {
                    evPanel.style.display = 'block';
                    evContent.innerHTML = ds.eventLog;
                } else {
                    evPanel.style.display = 'none';
                    evContent.innerHTML = '';
                }
            }
        }

