            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaMargin',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('healthDisplay', 'domainState.innovationHealth');

            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.periodManager && typeof sim.periodManager.addHook === 'function') {
                sim.periodManager.addHook('afterAdvance', function(st) { self._syncUI(st); });
                sim.periodManager.addHook('onComplete', function(st) { self._syncUI(st); });
            }
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                sim.eventBus.on('period:undone', function(st) { self._syncUI(st); });
                sim.eventBus.on('language:changed', function() { self._syncUI(sim.state); });
            }
        }

